<script setup lang="ts">
const confirm=window.confirm.bind(window);
import { computed,ref,type ObjectDirective } from 'vue';import { useRoute,useRouter } from 'vue-router';
import { state,changed,flush,run,dueAssignments,assignmentFor,addAttempt,discardEmptyDuplicates,needsRepeat } from '../store';
import type { Assignment,Attempt } from '../domain/types';
import { assessmentRows,matchesAssignment,canFinishEvaluation,type AssessmentRow } from '../domain/worksheet';
const route=useRoute(),router=useRouter();const draft=computed(()=>state.drafts.find(d=>d.key===route.params.key));const work=computed(()=>draft.value?.students.find(w=>w.student_id===Number(route.params.student)));const position=computed(()=>draft.value?.students.findIndex(w=>w.student_id===work.value?.student_id)||0);
if(draft.value&&work.value&&discardEmptyDuplicates(work.value))changed(draft.value);
const due=computed(()=>draft.value&&work.value?dueAssignments(draft.value,work.value).filter(a=>(!a.id||!work.value!.removed_assignment_ids.includes(a.id))):[]);
const type=(a:Assignment)=>a.type==='revision'?'مراجعة':'حفظ جديد';
const hasRecordedWork=computed(()=>Boolean(work.value&&(canFinishEvaluation(work.value.assessments)||(!rows.value.length&&work.value.assignments.some(a=>a.assigned_here)))));
const canFinish=computed(()=>Boolean(work.value&&!work.value.archived&&hasRecordedWork.value&&!(work.value.composer?.open&&(work.value.composer.surah_name||work.value.composer.to_ayah))));
function mark(){if(work.value?.evaluated_at&&!hasRecordedWork.value){work.value.evaluated_at=null;work.value.attendance_status='not_marked'}if(draft.value)changed(draft.value)}
function assignment(a:Attempt){return draft.value&&work.value?assignmentFor(draft.value,work.value,a.quran_assignment_id,a.assignment_client_uuid):undefined}
const rows=computed(()=>{if(!work.value)return [];return assessmentRows(due.value,work.value.assessments).map(row=>({...row,assignment:row.assignment||(row.attempt?assignment(row.attempt):undefined)}))});
const notes=ref<Record<string,boolean>>({});
function resizeNote(el:HTMLTextAreaElement){el.style.height='auto';el.style.height=(el.scrollHeight+2)+'px'}
const vAutosize:ObjectDirective<HTMLTextAreaElement>={
 mounted(el){resizeNote(el);el.addEventListener('input',()=>resizeNote(el))},
 updated(el){resizeNote(el)}
};

function noteVisible(row:AssessmentRow){return notes.value[row.key]??Boolean(row.attempt?.comment)}
function ensureAttempt(row:AssessmentRow){
 if(!row.attempt&&row.assignment){addAttempt(draft.value!,work.value!,row.assignment);row.attempt=work.value!.assessments.find(a=>matchesAssignment(a,row.assignment!))}
 return row.attempt;
}
function editAssessment(row:AssessmentRow,field:'grade'|'comment',event:Event){const attempt=ensureAttempt(row);if(attempt){attempt[field]=(event.target as HTMLInputElement).value;mark()}}
function toggle(row:AssessmentRow,e:Event){const attempt=ensureAttempt(row);if(attempt){attempt.needs_repeat=(e.target as HTMLInputElement).checked;mark()}}
function composer(){work.value!.composer={open:true,surah_name:'',from_ayah:'1',to_ayah:'',type:'new_memorization'};mark()}
async function add(){const c=work.value!.composer!;const from=Number(c.from_ayah),to=Number(c.to_ayah);if(!state.cache?.surahs.some(s=>s.name===c.surah_name))throw Error('اختر سورة.');if(!Number.isInteger(from)||!Number.isInteger(to)||from<1||to<from)throw Error('أرقام الآيات موجبة، والنهاية لا تسبق البداية.');work.value!.assignments.push({assigned_here:true,student_id:work.value!.student_id,client_uuid:crypto.randomUUID(),surah_name:c.surah_name,from_ayah:from,to_ayah:to,type:c.type,is_passed:false});work.value!.composer=undefined;mark();await flush()}
function remove(a:Assignment){const used=state.drafts.some(d=>d.students.some(w=>w.assessments.some(x=>x.grade!==''&&((a.id&&x.quran_assignment_id===a.id)||(a.client_uuid&&x.assignment_client_uuid===a.client_uuid)))));if(a.assessments?.length||used){state.error='هذا الواجب مرتبط بتقييم. احتفظ به وبسجله.';return}if(!confirm('حذف الواجب غير المقيم؟'))return;work.value!.assignments=work.value!.assignments.filter(x=>!((a.id&&x.id===a.id)||(a.client_uuid&&x.client_uuid===a.client_uuid)));if(a.id)work.value!.removed_assignment_ids.push(a.id);work.value!.assessments=work.value!.assessments.filter(x=>!((a.id&&x.quran_assignment_id===a.id)||(a.client_uuid&&x.assignment_client_uuid===a.client_uuid)));mark()}
async function finish(){const w=work.value!;if(!canFinish.value)throw Error('أكمل تقييمًا بعلامة، أو أضف واجبًا جديدًا إذا لم توجد واجبات سابقة للتقييم.');if(w.composer?.open&&(w.composer.surah_name||w.composer.to_ayah))throw Error('أضف الواجب المفتوح أو تخلّ عنه أولًا.');if(w.assessments.some(a=>(a.grade!==''||a.id||a.comment?.trim())&&(a.grade===''||!Number.isFinite(Number(a.grade)))))throw Error('أدخل علامة رقمية لكل تقييم مسجل؛ العلامة الفارغة لا تعني صفرًا.');w.evaluated_at=new Date().toISOString();mark();await flush();await router.push('/session/'+draft.value!.key)}
function step(delta:number){const next=draft.value!.students[position.value+delta];if(next)void router.push(`/session/${draft.value!.key}/student/${next.student_id}`)}
</script>
<template><section v-if="draft&&work" class="worksheet"><div class="worksheet-toolbar"><div class="worksheet-context"><RouterLink class="back" :to="`/session/${draft.key}`"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h16m-6-6 6 6-6 6"/></svg>طلاب الحصة</RouterLink><p class="eyebrow">الطالب {{position+1}} من {{draft.students.length}}</p></div><div class="page-title"><div><h1>{{work.name}}</h1></div><span v-if="work.evaluated_at" class="badge synced">تم التسجيل</span></div><div class="worksheet-toolbar-actions"><RouterLink class="quiet" :to="`/session/${draft.key}/edit`">تعديل الحصة</RouterLink><button class="primary" :disabled="!canFinish||state.busy" aria-describedby="evaluation-requirement" @click="run(finish)">إنهاء الطالب ✓</button></div><p v-if="!canFinish&&!work.archived" id="evaluation-requirement" class="evaluation-requirement">{{rows.length?'أدخل علامة لتقييم واحد على الأقل لإتاحة إنهاء الطالب.':'أضف واجبًا جديدًا لإتاحة إنهاء الطالب.'}}</p></div><p v-if="work.archived" class="notice error">الطالب مؤرشف. يمكنك قراءة سجله؛ لا يمكن إرسال تغييرات عليه.</p><div class="worksheet-grid"><section class="card worksheet-section assessment-section">
 <h2>تقييم اليوم</h2>
 <p v-if="!rows.length" class="muted">لا توجد واجبات سابقة للتسميع. يمكنك إضافة واجب جديد ثم إنهاء الطالب.</p>
 <article v-for="row in rows" :key="row.key" class="assessment-item compact-assessment">
  <div class="assessment-header">
   <div class="assessment-passage"><strong>{{row.assignment?type(row.assignment):'واجب مؤرشف'}} · {{row.assignment?.surah_name||'غير متاح'}}</strong><p>الآيات <bdi>{{row.assignment?.from_ayah}}–{{row.assignment?.to_ayah}}</bdi><span v-if="row.assignment?.assessments?.length"> · السابق {{row.assignment.assessments.at(-1)?.grade}}</span></p></div>
   <label class="compact-grade"><span>العلامة</span><input :value="row.attempt?.grade??''" class="grade-input" type="text" inputmode="decimal" placeholder="—" :aria-label="'علامة '+(row.assignment?.surah_name||'المقطع')" :disabled="!row.assignment||row.attempt?.assignment_archived||work.archived" @input="editAssessment(row,'grade',$event)"></label>
  </div>
  <div class="assessment-controls"><label v-if="row.assignment&&!row.attempt?.assignment_archived" class="check"><input :checked="needsRepeat(work,row.assignment,row.attempt)" type="checkbox" :disabled="work.archived" @change="toggle(row,$event)">يحتاج إعادة</label><span v-else class="muted">مؤرشف</span><button type="button" class="note-toggle" :aria-expanded="noteVisible(row)" :aria-controls="'note-'+row.key" @click="notes[row.key]=!noteVisible(row)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h16v12H9l-5 4V5Z M8 9h8M8 13h5"/></svg>ملاحظة</button></div>
  <div v-if="noteVisible(row)" class="assessment-note"><label :for="'note-'+row.key" class="sr-only">ملاحظة {{row.assignment?.surah_name||'التقييم'}}</label><textarea v-autosize :id="'note-'+row.key" :value="row.attempt?.comment||''" rows="1" placeholder="ملاحظة اختيارية" :disabled="!row.assignment||row.attempt?.assignment_archived||work.archived" @input="editAssessment(row,'comment',$event)"></textarea></div>
 </article>
 </section><section class="card worksheet-section next-assignments"><div class="between next-heading"><div class="next-title"><h2>الواجبات التالية</h2><span class="optional-label">اختياري</span></div><span v-if="work.assignments.some(a=>a.assigned_here)" class="badge">{{work.assignments.filter(a=>a.assigned_here).length}}</span></div><article v-for="a in work.assignments.filter(a=>a.assigned_here)" :key="a.client_uuid!" class="assignment-row"><div><strong>{{type(a)}} · {{a.surah_name}}</strong><p class="muted">الآيات <bdi>{{a.from_ayah}}–{{a.to_ayah}}</bdi></p></div><button type="button" class="danger remove-assignment" :aria-label="'إزالة واجب '+a.surah_name" title="إزالة الواجب" :disabled="work.archived" @click="remove(a)">×</button></article><button v-if="!work.composer?.open" class="quiet full" :disabled="work.archived" @click="composer">＋ واجب جديد</button><form v-else class="form composer" @submit.prevent="run(add)"><div class="assignment-selects"><label>النوع<select v-model="work.composer.type" @change="mark"><option value="new_memorization">حفظ جديد</option><option value="revision">مراجعة</option></select></label><label>السورة<select v-model="work.composer.surah_name" required @change="mark"><option value="" disabled>اختر سورة</option><option v-for="s in state.cache?.surahs" :key="s.id" :value="s.name">{{s.name}}</option></select></label></div><div class="fields"><label>من الآية<input v-model="work.composer.from_ayah" type="number" min="1" step="1" required @input="mark"></label><label>إلى الآية<input v-model="work.composer.to_ayah" type="number" min="1" step="1" required @input="mark"></label></div><div class="actions"><button class="primary">إضافة</button><button class="quiet" type="button" @click="()=>{if(!(work!.composer?.surah_name||work!.composer?.to_ayah)||confirm('التخلّي عن الواجب الذي لم يُضف؟')){work!.composer=undefined;mark()}}">إلغاء</button></div></form></section></div><div class="evaluation-bottom"><div class="between"><button class="quiet" :disabled="position===0" @click="step(-1)">→ السابق</button><button class="quiet" :disabled="position===draft.students.length-1" @click="step(1)">التالي ←</button></div></div></section><p v-else class="empty">الطالب أو الحصة غير متاحين لهذا الحساب.</p></template>
